def _catalog(text):
    """One focus per line, pipe-separated independent contexts."""
    rows = {}
    for line in text.strip().splitlines():
        focus, *frames = line.strip().split('|')
        assert focus not in rows
        rows[focus] = tuple(frames)
    return rows


