def _render(frame, rng, variant=0, **slots):
    # A local alternative is selected by index, so both members occur for
    # protection; proper-name alternatives alternate across names as well.
    frame = re.sub(r'\[([^][]+)\]', lambda m: m[1].split('/')[variant % len(m[1].split('/'))], frame)
    for category, expressions in TIME_POOLS.items():
        marker = '{' + category + '}'
        if marker in frame:
            slots[category] = rng.choice(expressions) if rng.random() < .65 else ''
    slots.setdefault('p', rng.choice(PEOPLE))
    return upper_first(' '.join(frame.format(**slots).split()))


def sentences(seed=3200):
    """Fresh dictionaries, deterministic order/content, no global RNG mutation."""
    rng = random.Random(seed)
    result, seen = [], set()

    def add(text, kind, focus, **metadata):
        key = canonical(text)
        if key in seen:
            return
        assert 3 <= len(text.split()) <= 14, text
        assert 18 <= len(text.encode('utf-8')) <= 160, text
        assert text[0].isupper() and text[-1] in '.?!'
        seen.add(key)
        result.append({'target': text, 'kind': kind, 'focus': focus, **metadata})

    assert set(SPELLING_FRAMES) == {c for c, _, _ in MISSPELLINGS + MISSPELLINGS_V32}
    for focus, frames in SPELLING_FRAMES.items():
        for frame in frames:
            add(_render(frame, rng), 'yazım', focus)

    for places, frames in ((I_PLACES + DOTTED_PLACES, PLACE_FRAMES),
                           (I_PEOPLE + DOTTED_PEOPLE, PERSON_FRAMES)):
        for index, name in enumerate(places):
            forms = {case: suffix(name, case) for case in ('dat', 'abl', 'loc', 'gen', 'with')}
            # Every two-person context crosses the I/İ boundary.
            others = DOTTED_PEOPLE if name.startswith('I') else I_PEOPLE
            for frame_index, frame in enumerate(frames):
                text = _render(frame, rng, variant=index + frame_index, name=name,
                               other=rng.choice(others), **forms)
                names = list(dict.fromkeys(word for word in re.findall(r'\b\w+\b', text)
                                           if word in NAMES_V32))
                add(text, 'özel_ad', name, names=names)
    for focus, frames in INITIAL_COMMON.items():
        for frame in frames:
            add(_render(frame, rng), 'özel_ad', focus, names=[])

    for focus, frames in PROTECTION.items():
        for frame in frames:
            # Share slots between lexical alternatives; neither person nor time
            # is used as an expansion axis.
            person = rng.choice(PEOPLE)
            times = {category: rng.choice(pool) if rng.random() < .65 else ''
                     for category, pool in TIME_POOLS.items()}
            frame = frame.format(p=person, **times)
            for variant in (0, 1):
                add(_render(frame, rng, variant), 'koruma', focus)

    rng.shuffle(result)
    return result
